changeSet.sql:
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT cpd.product_id, 'length_m', trim(to_char(cpd.standard_length, 'FM999999990.00')) FROM construction_product_details cpd WHERE cpd.standard_length IS NOT NULL ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT cpd.product_id, 'width_m', trim(to_char(cpd.width, 'FM999999990.00')) FROM construction_product_details cpd WHERE cpd.width IS NOT NULL ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT cpd.product_id, 'thickness_mm', trim(to_char(cpd.thickness, 'FM999999990.00')) FROM construction_product_details cpd WHERE cpd.thickness IS NOT NULL ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT cpd.product_id, 'allow_cutting', 'true' FROM construction_product_details cpd WHERE cpd.allow_cutting = TRUE ON CONFLICT (product_id, field_key) DO NOTHING;
